#' Communtability (IFCC, 2018-B)
#'
#' 
#' @param data .
#' @param csid .
#' @param csxy .
#' @param rmid .
#' @param rmp .
#' @param rmxy .
#' @param ln .
#' @param logscale .
#' @param ef .
#' @param alpha .
#' @param g.alpha .
#' @param C .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$text} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$descriptive$cso} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$descriptive$rmo} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$descriptive$mcrm} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$descriptive$mccs} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$descriptive$sxsy} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$descriptive$pp.mp.x} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$descriptive$pp.mp.y} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$descriptive$dp.b.c} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$cmp} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$ttcs} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$tdcs} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$rma} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$rmxa} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$rmya} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$sec} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$seft} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$c} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$ct} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$ci} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$rmxa$asDF}
#'
#' \code{as.data.frame(results$rmxa)}
#'
#' @export
CommutabilityIFCC <- function(
    data,
    csid,
    csxy,
    rmid,
    rmp,
    rmxy,
    ln,
    logscale = TRUE,
    ef = 1.9,
    alpha = 0.05,
    g.alpha = 0.01,
    C = 12) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("CommutabilityIFCC requires jmvcore to be installed (restart may be required)")

    if ( ! missing(csid)) csid <- jmvcore::resolveQuo(jmvcore::enquo(csid))
    if ( ! missing(rmid)) rmid <- jmvcore::resolveQuo(jmvcore::enquo(rmid))
    if ( ! missing(rmp)) rmp <- jmvcore::resolveQuo(jmvcore::enquo(rmp))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(csid), csid, NULL),
            `if`( ! missing(rmid), rmid, NULL),
            `if`( ! missing(rmp), rmp, NULL))


    options <- CommutabilityIFCCOptions$new(
        csid = csid,
        csxy = csxy,
        rmid = rmid,
        rmp = rmp,
        rmxy = rmxy,
        ln = ln,
        logscale = logscale,
        ef = ef,
        alpha = alpha,
        g.alpha = g.alpha,
        C = C)

    analysis <- CommutabilityIFCCClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

